#include <stdio.h>

int main(void) {
    char word[101];
    scanf("%100s", word);
    int n = 0;
    while (word[n] != '\0') {
        n++;
    }
    int palindrome = 1;
    for (int i = 0; i < n / 2; i++) {
        if (word[i] != word[n - 1 - i]) {
            palindrome = 0;
            break;
        }
    }
    printf("%s\n", palindrome ? "да" : "нет");
    return 0;
}

