#include <stdio.h>

int main(void) {
    char line[1002];
    if (fgets(line, sizeof(line), stdin) == NULL) {
        printf("0\n");
        return 0;
    }
    int words = 0;
    for (int i = 0; line[i] != '\0' && line[i] != '\n'; i++) {
        int is_space = line[i] == ' ';
        int prev_space = i == 0 || line[i - 1] == ' ';
        if (!is_space && prev_space) {
            words++;
        }
    }
    printf("%d\n", words);
    return 0;
}

