int main(void) {
    char digits[19];
    scanf("%18s", digits);
    long long value = 0;
    for (int i = 0; digits[i] != '\0'; i++) {
        value = value * 10 + (digits[i] - '0');
    }
    printf("%lld\n", value * 2);
    return 0;
}

